//! #3004 P4-1: `hooks-plan` / `hooks-apply` report the first `moai` on PATH as `moai_on_path`
//! (`resolved`, `wrong_generation`, `binary_unresolved`, `not_probed`) next to the unchanged
//! `hook_binary`, and `hook_status` carries `binary` / `binary_generation`. The fakes are shell
//! scripts in a temporary folder, the project and HOME are temporary, and the real PATH, HOME
//! and installed `moai` are never read. No generated byte changes and nothing is gated yet.
#![cfg(unix)]

mod common;

use common::CleanEnv as _;
use serde_json::{json, Value};
use std::{
    fs,
    path::{Path, PathBuf},
    process::{Command, Stdio},
};
use tempfile::TempDir;

const SIGNATURE: &str = "moai-cli 1.2.3 (rust)";

/// One temporary world: `root/project` (the project being planned), `root/home` (HOME) and
/// `root/bin` (a PATH folder outside the project).
struct World {
    _dir: TempDir,
    root: PathBuf,
    project: PathBuf,
    home: PathBuf,
    bin: PathBuf,
}

fn world() -> World {
    let dir = TempDir::new().unwrap();
    let root = fs::canonicalize(dir.path()).unwrap();
    let w = World {
        project: root.join("project"),
        home: root.join("home"),
        bin: root.join("bin"),
        root,
        _dir: dir,
    };
    for d in [&w.project.join(".moai-cli"), &w.home, &w.bin] {
        fs::create_dir_all(d).unwrap();
    }
    w
}

fn script(dir: &Path, name: &str, body: &str) -> PathBuf {
    fs::create_dir_all(dir).unwrap();
    let p = dir.join(name);
    common::write_executable(&p, body);
    p
}

/// A `moai` that prints `line` for `--version`.
fn printing(line: &str) -> String {
    format!("#!/bin/sh\nprintf '%s\\n' '{line}'\n")
}

/// Runs `moai ARGS` in `cwd` with a cleared environment plus HOME, PATH and `extra`; returns
/// the unwrapped `result`.
fn run(w: &World, cwd: &Path, args: &[&str], path_env: &str, extra: &[(&str, &str)]) -> Value {
    let mut cmd = Command::new(common::MOAI_BIN);
    cmd.clean_env()
        .args(args)
        .current_dir(cwd)
        .env("HOME", &w.home)
        .env("PATH", path_env)
        .env("GIT_CONFIG_GLOBAL", "/dev/null")
        .env("GIT_CONFIG_SYSTEM", "/dev/null")
        .stdin(Stdio::null());
    for (k, v) in extra {
        cmd.env(k, v);
    }
    let out = cmd.output().unwrap();
    let v: Value = serde_json::from_slice(&out.stdout)
        .unwrap_or_else(|_| panic!("{}", String::from_utf8_lossy(&out.stderr)));
    assert_eq!(v["ok"], json!(true), "{v}");
    v["result"].clone()
}

fn plan(w: &World, path_env: &str, extra: &[(&str, &str)]) -> Value {
    let project = w.project.to_str().unwrap();
    run(
        w,
        &w.root,
        &["hooks-plan", project, "--host", "claude"],
        path_env,
        extra,
    )
}

/// The `moai_on_path` object of a plan whose PATH is `path_env`.
fn moai_on_path(w: &World, path_env: &str, extra: &[(&str, &str)]) -> Value {
    let p = plan(w, path_env, extra);
    // The status block repeats the state and the generation as plain strings.
    assert_eq!(
        p["hook_status"]["binary"], p["moai_on_path"]["state"],
        "{p}"
    );
    assert_eq!(
        p["hook_status"]["binary_generation"], p["moai_on_path"]["generation"],
        "{p}"
    );
    p["moai_on_path"].clone()
}

#[test]
fn the_rust_build_resolves_under_both_names() {
    for line in [SIGNATURE, "moai 1.2.3 (rust)"] {
        let w = world();
        let marker = w.root.join("ran");
        script(
            &w.bin,
            "moai",
            &format!(
                "#!/bin/sh\ntouch '{}'\nprintf '%s\\n' '{line}'\n",
                marker.display()
            ),
        );
        let m = moai_on_path(&w, w.bin.to_str().unwrap(), &[]);
        assert_eq!(m["state"], json!("resolved"), "{line}: {m}");
        assert_eq!(m["generation"], json!("rust"), "{m}");
        assert_eq!(m["version_line"], json!(line), "{m}");
        assert_eq!(m["name"], json!("moai"));
        assert_eq!(m["path"], json!(w.bin.join("moai").to_str().unwrap()));
        assert!(m.get("note").is_none(), "{m}");
        assert!(marker.exists(), "the outside fake was probed");
    }
}

#[test]
fn a_go_or_silent_or_hanging_moai_is_the_wrong_generation() {
    // (what the fake does, generation, version_line)
    let cases: [(&str, &str, Value); 4] = [
        ("moai-adk v3.2.1-rc.6", "go", json!("moai-adk v3.2.1-rc.6")),
        ("moai 3.2.0", "go", json!("moai 3.2.0")),
        ("", "unknown", json!(null)),
        ("moai-cli 1.2.3", "unknown", json!("moai-cli 1.2.3")),
    ];
    for (line, generation, version_line) in cases {
        let w = world();
        let body = if line.is_empty() {
            "#!/bin/sh\nexit 0\n".to_string()
        } else {
            printing(line)
        };
        script(&w.bin, "moai", &body);
        let m = moai_on_path(&w, w.bin.to_str().unwrap(), &[]);
        assert_eq!(m["state"], json!("wrong_generation"), "{line:?}: {m}");
        assert_eq!(m["generation"], json!(generation), "{line:?}: {m}");
        assert_eq!(m["version_line"], version_line, "{line:?}: {m}");
        assert_eq!(m["path"], json!(w.bin.join("moai").to_str().unwrap()));
        assert!(m["basis"].as_str().unwrap().starts_with("--version"), "{m}");
        let note = m["note"].as_str().unwrap();
        for part in [
            "not the Rust build",
            "non-blocking",
            "claim guard would not run",
            "first on PATH",
            "moai update",
        ] {
            assert!(note.contains(part), "{part}: {note}");
        }
    }

    // A hang is killed at the probe limit (injected; debug builds only) and reads as unknown.
    let w = world();
    script(
        &w.bin,
        "moai",
        "#!/bin/sh\nsleep 30\necho 'moai-cli 1.2.3 (rust)'\n",
    );
    let m = moai_on_path(
        &w,
        w.bin.to_str().unwrap(),
        &[("MOAI_CLI_TEST_PROBE_TIMEOUT_MS", "1000")],
    );
    assert_eq!(m["state"], json!("wrong_generation"), "{m}");
    assert_eq!(m["generation"], json!("unknown"), "{m}");
    assert_eq!(m["version_line"], json!(null), "{m}");
    assert_eq!(m["basis"], json!("--version gave no line"), "{m}");
}

/// One `hooks-plan` runs the PATH `moai` once with the single argument `--version`, although
/// two blocks of the result (`moai_on_path`, `hook_status`) report it.
#[test]
fn one_plan_probes_the_moai_once_with_only_version() {
    let w = world();
    let log = w.root.join("calls");
    script(
        &w.bin,
        "moai",
        &format!(
            "#!/bin/sh\necho \"$#:$*\" >> '{}'\nprintf '%s\\n' '{SIGNATURE}'\n",
            log.display()
        ),
    );
    let p = plan(&w, w.bin.to_str().unwrap(), &[]);
    assert_eq!(p["moai_on_path"]["state"], json!("resolved"), "{p}");
    assert_eq!(p["hook_status"]["binary"], json!("resolved"), "{p}");
    assert_eq!(fs::read_to_string(&log).unwrap(), "1:--version\n");
}

#[test]
fn no_moai_on_the_path_is_unresolved() {
    let w = world();
    let m = moai_on_path(&w, w.bin.to_str().unwrap(), &[]);
    assert_eq!(m["state"], json!("binary_unresolved"), "{m}");
    assert_eq!(m["generation"], json!("absent"), "{m}");
    assert_eq!(m["name"], json!("moai"));
    assert!(m.get("path").is_none(), "{m}");
}

/// A relative PATH hit and a hit inside the project tree are repository content: reported as
/// `not_probed` with reason `project_tree` and never run. The markers prove the fakes never ran;
/// the sibling folder whose name only starts like the project's is still probed.
#[test]
fn a_relative_or_in_project_moai_is_never_run() {
    let ran = |w: &World, name: &str| w.root.join(name);
    let marking = |w: &World, name: &str| {
        format!(
            "#!/bin/sh\ntouch '{}'\nprintf '%s\\n' '{SIGNATURE}'\n",
            ran(w, name).display()
        )
    };

    // Relative PATH entry (`relbin`, resolved against the process's working folder).
    let w = world();
    script(&w.root.join("relbin"), "moai", &marking(&w, "ran-relative"));
    let m = moai_on_path(&w, "relbin", &[]);
    assert_eq!(m["state"], json!("not_probed"), "{m}");
    assert_eq!(m["reason"], json!("project_tree"), "{m}");
    assert_eq!(m["generation"], json!("not_probed"), "{m}");
    assert!(!ran(&w, "ran-relative").exists(), "a relative hit was run");

    // Absolute PATH entry inside the project.
    let w = world();
    let inside = w.project.join("bin");
    script(&inside, "moai", &marking(&w, "ran-inside"));
    let m = moai_on_path(&w, inside.to_str().unwrap(), &[]);
    assert_eq!(m["state"], json!("not_probed"), "{m}");
    assert_eq!(m["reason"], json!("project_tree"), "{m}");
    assert_eq!(m["path"], json!(inside.join("moai").to_str().unwrap()));
    assert!(!ran(&w, "ran-inside").exists(), "an in-project hit was run");

    // A PATH folder outside the project that is a link into it: the real file is inside.
    let w = world();
    let inside = w.project.join("bin");
    script(&inside, "moai", &marking(&w, "ran-linked"));
    let link = w.root.join("linked");
    std::os::unix::fs::symlink(&inside, &link).unwrap();
    let m = moai_on_path(&w, link.to_str().unwrap(), &[]);
    assert_eq!(m["state"], json!("not_probed"), "{m}");
    assert!(!ran(&w, "ran-linked").exists(), "a linked hit was run");

    // A link inside the project to a file outside it: the PATH hit is the project's own entry,
    // so it is not run either, whatever it points to.
    let w = world();
    let real = w.root.join("real");
    script(&real, "moai", &marking(&w, "ran-outward"));
    let inside = w.project.join("bin");
    fs::create_dir_all(&inside).unwrap();
    std::os::unix::fs::symlink(real.join("moai"), inside.join("moai")).unwrap();
    let m = moai_on_path(&w, inside.to_str().unwrap(), &[]);
    assert_eq!(m["state"], json!("not_probed"), "{m}");
    assert!(
        !ran(&w, "ran-outward").exists(),
        "an in-project link was run"
    );

    // The other direction: a folder whose name merely starts like the project's is outside it.
    let w = world();
    let near = w.root.join("project-bin");
    script(&near, "moai", &marking(&w, "ran-near"));
    let m = moai_on_path(&w, near.to_str().unwrap(), &[]);
    assert_eq!(m["state"], json!("resolved"), "{m}");
    assert!(ran(&w, "ran-near").exists(), "an outside hit is probed");
}

/// The routing shim finds the Rust binary through `$HOME`; the probe's environment is cleared,
/// so only a passed HOME makes it Rust. Nothing else of the caller's environment arrives.
#[test]
fn only_home_reaches_the_probed_moai() {
    let w = world();
    script(
        &w.home.join(".moai-cli/path"),
        "moai-cli",
        &printing(SIGNATURE),
    );
    script(
        &w.bin,
        "moai",
        "#!/bin/sh\nRUST=\"${MOAI_RUST_BIN:-$HOME/.moai-cli/path/moai-cli}\"\n\
         if [ -x \"$RUST\" ]; then exec \"$RUST\" \"$@\"; fi\necho 'moai-adk v3.2.1'\n",
    );
    let m = moai_on_path(
        &w,
        w.bin.to_str().unwrap(),
        &[("MOAI_RUST_BIN", "/nonexistent")],
    );
    // The caller's MOAI_RUST_BIN did not arrive, so the shim used `$HOME/…` and found Rust.
    assert_eq!(m["state"], json!("resolved"), "{m}");
    assert_eq!(m["version_line"], json!(SIGNATURE), "{m}");

    // Nothing under HOME for the shim to find: the same shim reads as Go.
    fs::remove_file(w.home.join(".moai-cli/path/moai-cli")).unwrap();
    let m = moai_on_path(&w, w.bin.to_str().unwrap(), &[]);
    assert_eq!(m["state"], json!("wrong_generation"), "{m}");
    assert_eq!(m["generation"], json!("go"), "{m}");

    // The child's variable names: HOME and the fixed PATH, no token of the caller.
    let w = world();
    script(
        &w.bin,
        "moai",
        "#!/bin/sh\nprintf 'moai-adk 1 names=%s\\n' \"$(env | cut -d= -f1 | sort | tr '\\n' ,)\"\n\
         ",
    );
    let m = moai_on_path(
        &w,
        w.bin.to_str().unwrap(),
        &[("MOAI_P41_TOKEN", "sk-test-not-real"), ("GH_TOKEN", "x")],
    );
    let line = m["version_line"].as_str().unwrap();
    assert!(line.contains("HOME"), "{line}");
    assert!(line.contains("PATH"), "{line}");
    assert!(!line.contains("TOKEN"), "{line}");
}

/// The probe limit (injected, debug builds only): a fake that answers well inside it is
/// probed, one that answers only well after it is killed and reads as unknown.
#[test]
fn the_probe_time_limit_has_a_pass_and_a_fail_side() {
    let limit = [("MOAI_CLI_TEST_PROBE_TIMEOUT_MS", "2000")];
    let w = world();
    script(
        &w.bin,
        "moai",
        &format!("#!/bin/sh\nsleep 0.2\nprintf '%s\\n' '{SIGNATURE}'\n"),
    );
    let m = moai_on_path(&w, w.bin.to_str().unwrap(), &limit);
    assert_eq!(m["state"], json!("resolved"), "under the limit: {m}");

    let w = world();
    script(
        &w.bin,
        "moai",
        &format!("#!/bin/sh\nsleep 6\nprintf '%s\\n' '{SIGNATURE}'\n"),
    );
    let m = moai_on_path(&w, w.bin.to_str().unwrap(), &limit);
    assert_eq!(m["state"], json!("wrong_generation"), "over the limit: {m}");
    assert_eq!(m["generation"], json!("unknown"), "{m}");
}

/// `--version` stdout is read up to 4096 bytes: a signature that ends at byte 4096 counts, one
/// that ends at byte 4097 is cut and reads as unknown. Leading blanks move the signature.
#[test]
fn the_stdout_cap_has_an_accepted_and_a_refused_edge() {
    let sig = "moai-cli 1.0 (rust)";
    for (blanks, state) in [
        (4096 - sig.len(), "resolved"),
        (4096 - sig.len() + 1, "wrong_generation"),
    ] {
        let w = world();
        script(
            &w.bin,
            "moai",
            &format!("#!/bin/sh\nprintf '%{blanks}s' ''\nprintf '%s' '{sig}'\n"),
        );
        let m = moai_on_path(&w, w.bin.to_str().unwrap(), &[]);
        assert_eq!(m["state"], json!(state), "{blanks} blanks: {m}");
    }
}

/// The reported first line is at most 200 characters: a Rust line of exactly 200 is accepted,
/// one of 201 loses its closing `)` to the cut and reads as unknown; a long Go line is cut to 200.
#[test]
fn the_first_line_cap_has_an_accepted_and_a_refused_edge() {
    let line_of = |len: usize| {
        let tail = " (rust)";
        let head = "moai-cli 1";
        format!("{head}{}{tail}", "0".repeat(len - head.len() - tail.len()))
    };
    for (len, state, kept) in [
        (200, "resolved", 200),
        (199, "resolved", 199),
        (201, "wrong_generation", 200),
    ] {
        let w = world();
        script(&w.bin, "moai", &printing(&line_of(len)));
        let m = moai_on_path(&w, w.bin.to_str().unwrap(), &[]);
        assert_eq!(m["state"], json!(state), "{len} characters: {m}");
        assert_eq!(
            m["version_line"].as_str().unwrap().chars().count(),
            kept,
            "{len} characters: {m}"
        );
    }
    let w = world();
    script(
        &w.bin,
        "moai",
        &printing(&format!("moai-adk 3 {}", "x".repeat(400))),
    );
    let m = moai_on_path(&w, w.bin.to_str().unwrap(), &[]);
    assert_eq!(m["generation"], json!("go"), "{m}");
    assert_eq!(m["version_line"].as_str().unwrap().chars().count(), 200);
}

/// The old fields keep their meaning: `hook_binary` only looks up `moai-cli`, `hooks_active`
/// follows it and never turns true, and a wrong-generation `moai` changes neither.
#[test]
fn the_hook_binary_fields_are_unchanged() {
    let w = world();
    let path_env = w.bin.to_str().unwrap();
    script(&w.bin, "moai", &printing("moai-adk v3.2.1-rc.6"));
    let p = plan(&w, path_env, &[]);
    assert_eq!(p["hook_binary"]["name"], json!("moai-cli"), "{p}");
    assert_eq!(p["hook_binary"]["state"], json!("binary_unresolved"), "{p}");
    assert_eq!(p["hooks_active"], json!(false), "{p}");
    assert_eq!(p["moai_on_path"]["state"], json!("wrong_generation"), "{p}");
    assert_eq!(p["hook_status"]["installed"], json!(false), "{p}");

    script(&w.bin, "moai-cli", "#!/bin/sh\nexit 0\n");
    let p = plan(&w, path_env, &[]);
    assert_eq!(p["hook_binary"]["state"], json!("resolved"), "{p}");
    assert_eq!(p["hooks_active"], json!("not_run"), "{p}");
    assert_eq!(p["moai_on_path"]["state"], json!("wrong_generation"), "{p}");
    assert_eq!(p["hook_status"]["installed"], json!(true), "{p}");

    // Applying reports the same field and still writes `moai-cli` into the hook file.
    let project = w.project.to_str().unwrap();
    let applied = run(
        &w,
        &w.root,
        &[
            "hooks-apply",
            project,
            "--host",
            "codex",
            "--plan-digest",
            &plan_digest(&w, path_env, "codex"),
            "--permission-reference",
            "test-3004",
        ],
        path_env,
        &[],
    );
    assert_eq!(applied["moai_on_path"]["state"], json!("wrong_generation"));
    assert_eq!(applied["hook_binary"]["name"], json!("moai-cli"));
    let file = fs::read_to_string(w.project.join(".codex/hooks.json")).unwrap();
    assert!(
        file.contains("\"moai-cli claim-verify . --hook\""),
        "{file}"
    );
}

fn plan_digest(w: &World, path_env: &str, host: &str) -> String {
    let project = w.project.to_str().unwrap();
    let p = run(
        w,
        &w.root,
        &["hooks-plan", project, "--host", host],
        path_env,
        &[],
    );
    p["plan_digest"].as_str().unwrap().to_string()
}
